export function focusTransition({angularDistanceDeg=0,scope='COUNTRY',reducedMotion=false}={}){const base=scope==='CITY'?0.9:scope==='COUNTRY'?1.2:1.5;const duration=reducedMotion?0:Math.max(0.4,Math.min(1.8,base+angularDistanceDeg/180*0.4));return{durationSeconds:duration,easing:reducedMotion?'INSTANT':'SMOOTH_EASE_IN_OUT',overshoot:false,rule:'NO_DRAMATIC_ORBIT_IF_IT_HIDES_DATA_CONTEXT'};}
